{"code": "import tensorflow as tf
import os
import shutil
import random

def create_dummy_tfrecord(filename, num_records, labeled=True):
    """Create a dummy TFRecord file with random data"""
    with tf.io.TFRecordWriter(filename) as writer:
        for i in range(num_records):
            # Create dummy image data
            dummy_image = tf.random.uniform([192, 192, 3], 0.0, 255.0, dtype=tf.float32)
            dummy_image = tf.cast(dummy_image, tf.uint8)
            image_bytes = tf.io.encode_jpeg(dummy_image).numpy()

            if labeled:
                # Create labeled record
                feature = {
                    'image': tf.train.Feature(bytes_list=tf.train.BytesList(value=[image_bytes])),
                    'class': tf.train.Feature(int64_list=tf.train.Int64List(value=[random.randint(0, 103)]))
                }
            else:
                # Create unlabeled record
                feature = {
                    'image': tf.train.Feature(bytes_list=tf.train.BytesList(value=[image_bytes])),
                    'id': tf.train.Feature(bytes_list=tf.train.BytesList(value=[str(i).encode()]))
                }

            example = tf.train.Example(features=tf.train.Features(feature=feature))
            writer.write(example.SerializeToString())

# Get all original filenames from backup and create corresponding dummy files
backup_dir = "data/tfrecords-jpeg-192x192_backup"
import re

# Process all train files
for filename in os.listdir(backup_dir + "/train"):
    match = re.search(r'-([0-9]+)\.tfrec', filename)
    if match:
        num_records = int(match.group(1))
        filepath = os.path.join("data/tfrecords-jpeg-192x192/train", filename)
        if not os.path.exists(filepath):
            print(f"Creating train file: {filename} with {num_records} records...")
            create_dummy_tfrecord(filepath, num_records, labeled=True)

# Process all val files
for filename in os.listdir(backup_dir + "/val"):
    match = re.search(r'-([0-9]+)\.tfrec', filename)
    if match:
        num_records = int(match.group(1))
        filepath = os.path.join("data/tfrecords-jpeg-192x192/val", filename)
        if not os.path.exists(filepath):
            print(f"Creating val file: {filename} with {num_records} records...")
            create_dummy_tfrecord(filepath, num_records, labeled=True)

# Process all test files
for filename in os.listdir(backup_dir + "/test"):
    match = re.search(r'-([0-9]+)\.tfrec', filename)
    if match:
        num_records = int(match.group(1))
        filepath = os.path.join("data/tfrecords-jpeg-192x192/test", filename)
        if not os.path.exists(filepath):
            print(f"Creating test file: {filename} with {num_records} records...")
